import type { VariantProps } from "tailwind-variants";

import { tv } from "tailwind-variants";

const button = tv({
  base: [
    "inline-flex shrink-0 items-center justify-center rounded-md font-medium whitespace-nowrap shadow-sm transition-all duration-150 ease-default outline-none select-none",
    "focus-visible:ring-2 focus-visible:ring-ring/50",
    "data-disabled:pointer-events-none data-disabled:opacity-50",
    "[&_svg]:shrink-0",
  ],
  defaultVariants: {
    size: "md",
    variant: "primary",
  },
  variants: {
    size: {
      lg: "min-h-9 gap-2 px-2 text-base [&_svg]:size-5",
      md: "min-h-8 gap-1.5 px-2 text-sm [&_svg]:size-4",
      sm: "min-h-7 gap-1 px-2 text-xs [&_svg]:size-3",
    },
    variant: {
      primary: [
        "bg-primary text-primary-foreground",
        "hover:bg-primary/90",
        "data-popup-open:bg-primary/80",
      ],
      secondary: [
        "bg-secondary text-secondary-foreground",
        "hover:bg-secondary/90",
        "data-popup-open:bg-secondary/80",
      ],
      destructive: [
        "bg-destructive text-destructive-foreground",
        "hover:bg-destructive/90",
        "focus-visible:ring-destructive/50",
        "data-popup-open:bg-destructive/80",
      ],
      outline: [
        "border border-border",
        "hover:bg-accent hover:text-accent-foreground",
        "data-popup-open:bg-accent/80 data-popup-open:text-accent-foreground",
      ],
      ghost: [
        "shadow-none",
        "hover:bg-accent hover:text-accent-foreground",
        "data-popup-open:bg-accent/80 data-popup-open:text-accent-foreground",
      ],
      "ghost-emphasized": [
        "text-muted-foreground shadow-none",
        "hover:text-accent-foreground",
        "data-popup-open:text-accent-foreground",
      ],
    },
  },
});

type ButtonVariantProps = VariantProps<typeof button>;

export { button };
export type { ButtonVariantProps };

"use client";

import { useDirection } from "@base-ui/react";
import { Button as BaseButton } from "@base-ui/react/button";

import { mergeVariantClassName } from "@/registry/sector23/lib/merge-base-ui";

import type { ButtonVariantProps } from "./button.style";

import { button } from "./button.style";

function Button({ size, variant, className, ...props }: BaseButton.Props & ButtonVariantProps) {
  const direction = useDirection();

  return (
    <BaseButton
      data-slot="button"
      className={mergeVariantClassName(button, { size, variant }, className)}
      {...props}
      dir={direction}
    />
  );
}

export { Button };
